import type { JsonObject } from "@commissary/json";

/**
 * Golden translator cases (`test/fixtures/translator/`, generated by `tools/fixturegen/translator`) whose expected
 * request predates an upstream change Commissary has ported, by `<from>-><to> <case name>`: the `max_tokens` each must
 * now produce (ticket C2, Go `0d18d3b3`). A Chat Completions request without `max_tokens` gets the catalog's output
 * limit for its model (the harness's `catalogLookup`) instead of the flat 32000 the fixtures recorded. The fixture
 * JSON stays untouched; F2 (#388) regenerates it and deletes this module.
 */
const ROWS: ReadonlyArray<readonly [string, number]> = [
  ["openai->claude request: images, files and cache control", 64000],
  ["openai->claude request: user turn with only an unsupported file is refused", 64000],
  ["openai->claude request: reasoning effort on a legacy budget model", 64000],
  ["openai->claude request: reasoning effort on an adaptive model", 128000],
  ["openai->claude request: reasoning effort none and auto", 128000],
  ["openai->claude request: reasoning effort auto", 128000],
  ["openai->claude request: allowed_tools choice filters tools", 64000],
  ["openai->claude request: function tool choice and response_format json_schema", 64000],
  ["openai->claude request: json_object format and none tool choice", 64000],
  ["openai->claude response: streamed thinking, text and tool calls", 64000],
  ["openai->claude response: non-stream message with tools and usage", 64000],
  ["openai->claude response: non-stream max_tokens", 64000],
  ["openai->claude response: non-stream refusal", 64000],
];

const PORTED_MAX_TOKENS_AHEAD_OF_FIXTURES: ReadonlyMap<string, number> = new Map(ROWS);

const used = new Set<string>();

/** The `max_tokens` the case `key` now produces, when its golden predates the port. */
export const portedMaxTokens = (key: string): number | undefined => {
  const maxTokens = PORTED_MAX_TOKENS_AHEAD_OF_FIXTURES.get(key);

  if (maxTokens !== undefined) used.add(key);

  return maxTokens;
};

/** The entries no case consumed: stale once the fixtures are regenerated or a case is renamed. */
export const unusedMaxTokensAheadEntries = (): string[] =>
  [...PORTED_MAX_TOKENS_AHEAD_OF_FIXTURES.keys()].filter((key) => !used.has(key));

/**
 * Golden response cases whose expected output predates the OpenAI -> Claude response fixes of ticket C3 (Go
 * `c449529e`, `9a7db8e3`, `6044c5d1`, `69637a66`), by `<from>-><to> <case name>`. `stream` maps a response line index
 * to the events it now emits (lines not listed keep their golden output); `nonStream` replaces the whole body.
 * `message_delta` waits for the trailing usage-only chunk or `[DONE]` instead of firing on the chunk that carries
 * `finish_reason`, and a top-level `reasoning_content` block precedes the text block. The fixture JSON stays
 * untouched; F2 (#388) regenerates it and deletes this module.
 */
export interface PortedResponse {
  readonly stream?: ReadonlyMap<number, ReadonlyArray<string>>;
  readonly nonStream?: string;
}

const sse = (type: string, payload: JsonObject): string =>
  `event: ${type}\ndata: ${JSON.stringify(payload)}\n\n`;

const messageStop = sse("message_stop", { type: "message_stop" });

const messageDelta = (stopReason: string, usage: JsonObject): string =>
  sse("message_delta", {
    type: "message_delta",
    delta: { stop_reason: stopReason, stop_sequence: null },
    usage,
  });

const AFTER_PARALLEL_TOOLS: ReadonlyArray<string> = [
  sse("content_block_delta", {
    type: "content_block_delta",
    index: 1,
    delta: { type: "input_json_delta", partial_json: '{"city":"Paris"}' },
  }),
  sse("content_block_stop", { type: "content_block_stop", index: 1 }),
  sse("content_block_start", {
    type: "content_block_start",
    index: 2,
    content_block: { type: "tool_use", id: "call_def", name: "noop", input: {} },
  }),
  sse("content_block_delta", {
    type: "content_block_delta",
    index: 2,
    delta: { type: "input_json_delta", partial_json: "{}" },
  }),
  sse("content_block_stop", { type: "content_block_stop", index: 2 }),
  sse("content_block_start", {
    type: "content_block_start",
    index: 3,
    content_block: { type: "text", text: "" },
  }),
  sse("content_block_delta", {
    type: "content_block_delta",
    index: 3,
    delta: { type: "text_delta", text: " now" },
  }),
  sse("content_block_stop", { type: "content_block_stop", index: 3 }),
];

const RESPONSE_ROWS: ReadonlyArray<readonly [string, PortedResponse]> = [
  [
    "claude->openai stream: tool calls with interleaved text, parallel calls and tool-name casing restored",
    {
      stream: new Map([
        [6, AFTER_PARALLEL_TOOLS],
        [
          7,
          [
            messageDelta("tool_use", {
              input_tokens: 5,
              output_tokens: 7,
              cache_read_input_tokens: 2,
              cache_creation_input_tokens: 3,
            }),
            messageStop,
          ],
        ],
      ]),
    },
  ],
  [
    "claude->openai stream: reasoning details only",
    {
      stream: new Map([
        [
          1,
          [
            sse("content_block_delta", {
              type: "content_block_delta",
              index: 0,
              delta: { type: "thinking_delta", thinking: "alt" },
            }),
            sse("content_block_stop", { type: "content_block_stop", index: 0 }),
            sse("content_block_start", {
              type: "content_block_start",
              index: 1,
              content_block: { type: "text", text: "" },
            }),
            sse("content_block_delta", {
              type: "content_block_delta",
              index: 1,
              delta: { type: "text_delta", text: "x" },
            }),
            sse("content_block_stop", { type: "content_block_stop", index: 1 }),
          ],
        ],
        [4, [messageDelta("end_turn", { input_tokens: 1, output_tokens: 1 }), messageStop]],
      ]),
    },
  ],
  [
    "claude->openai stream: late usage only chunk after stop is ignored",
    {
      stream: new Map([
        [
          0,
          [
            sse("message_start", {
              type: "message_start",
              message: {
                id: "c8",
                type: "message",
                role: "assistant",
                model: "m",
                content: [],
                stop_reason: null,
                stop_sequence: null,
                usage: { input_tokens: 0, output_tokens: 0 },
              },
            }),
            sse("content_block_start", {
              type: "content_block_start",
              index: 0,
              content_block: { type: "text", text: "" },
            }),
            sse("content_block_delta", {
              type: "content_block_delta",
              index: 0,
              delta: { type: "text_delta", text: "x" },
            }),
            sse("content_block_stop", { type: "content_block_stop", index: 0 }),
          ],
        ],
        // The trailing usage-only chunk is authoritative: output_tokens 2, not the preliminary 1.
        [1, [messageDelta("end_turn", { input_tokens: 3, output_tokens: 2 }), messageStop]],
      ]),
    },
  ],
  [
    "claude->openai non-stream: text, reasoning and tool calls with cache usage",
    {
      nonStream: JSON.stringify({
        id: "chatcmpl-9",
        type: "message",
        role: "assistant",
        model: "gpt-4o",
        content: [
          { type: "thinking", thinking: "because" },
          { type: "text", text: "The answer" },
          { type: "tool_use", id: "call_1", name: "get_weather", input: { city: "Paris" } },
          { type: "tool_use", id: "call_2", name: "noop", input: {} },
        ],
        stop_reason: "tool_use",
        stop_sequence: null,
        usage: {
          input_tokens: 15,
          output_tokens: 9,
          cache_read_input_tokens: 10,
          cache_creation_input_tokens: 5,
        },
      }),
    },
  ],
];

const PORTED_RESPONSES: ReadonlyMap<string, PortedResponse> = new Map(RESPONSE_ROWS);

const usedResponses = new Set<string>();

/** The response output the case `key` now produces, when its golden predates the C3 port. */
export const portedResponse = (key: string): PortedResponse | undefined => {
  const ported = PORTED_RESPONSES.get(key);

  if (ported !== undefined) usedResponses.add(key);

  return ported;
};

/** The response entries no case consumed: stale once the fixtures are regenerated or a case is renamed. */
export const unusedResponseAheadEntries = (): string[] =>
  [...PORTED_RESPONSES.keys()].filter((key) => !usedResponses.has(key));
